/**
 * Authentication Endpoints Router
 * Exposes authentication middleware functions as API endpoints
 */

import { Router } from 'express';
import { 
  login, 
  register, 
  logout, 
  changePassword, 
  forgotPassword, 
  resetPassword,
  authenticate 
} from '../middleware/auth';
import { validateRequest } from '../middleware/validateRequest';
import { authRateLimiter } from '../middleware/rateLimiter';
import { z } from 'zod';

const router = Router();

// Validation schemas
const loginSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string().min(1, 'Password is required'),
});

const registerSchema = z.object({
  email: z.string().email('Invalid email format'),
  password: z.string()
    .min(8, 'Password must be at least 8 characters')
    .regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, 'Password must contain at least one uppercase letter, one lowercase letter, and one number'),
  name: z.string().min(1, 'Name is required'),
  organizationId: z.number().optional(),
});

const changePasswordSchema = z.object({
  currentPassword: z.string().min(1, 'Current password is required'),
  newPassword: z.string().min(8, 'New password must be at least 8 characters'),
});

const forgotPasswordSchema = z.object({
  email: z.string().email('Invalid email format'),
});

const resetPasswordSchema = z.object({
  token: z.string().min(1, 'Reset token is required'),
  newPassword: z.string().min(8, 'New password must be at least 8 characters'),
});

// Public endpoints with rate limiting
router.post('/login', authRateLimiter, validateRequest(loginSchema), login);
router.post('/register', authRateLimiter, validateRequest(registerSchema), register);
router.post('/forgot-password', authRateLimiter, validateRequest(forgotPasswordSchema), forgotPassword);
router.post('/reset-password', authRateLimiter, validateRequest(resetPasswordSchema), resetPassword);

// Protected endpoints
router.post('/logout', authenticate, logout);
router.post('/change-password', authenticate, validateRequest(changePasswordSchema), changePassword);

// Session check endpoint
router.get('/me', authenticate, async (req, res) => {
  try {
    // Get prisma instance based on environment
    let prisma: any;
    
    if (process.env.NODE_ENV === 'test') {
      // For test environment, use the test prisma client
      try {
        const testModule = await import('../../tests/jest.setup');
        prisma = testModule.getTestPrismaClient();
      } catch (importError) {
        // If we can't import test setup, fall back to regular prisma
        const dbModule = await import('@teaching-engine/database');
        prisma = dbModule.prisma;
      }
    } else {
      // For production/development, use regular prisma
      const dbModule = await import('@teaching-engine/database');
      prisma = dbModule.prisma;
    }
    
    // Verify user still exists in database
    const user = await prisma.user.findUnique({
      where: { id: req.user!.id },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        active: true,
      },
    });

    if (!user || !user.active) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found',
      });
    }

    res.json({
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
      },
    });
  } catch (error: any) {
    // Log the error for debugging
    console.error('Error in /auth/me endpoint:', error);
    
    // If it's a "record not found" error, return 404
    if (error.code === 'P2025' || (error.message && error.message.includes('not found'))) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found',
      });
    }
    
    // For other errors, return 500
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve user information',
    });
  }
});

export default router;